library(shiny)
library(bslib)
library(DT)

# Setup persistent directory
audio_dir <- file.path(tempdir(), "audio_app")
if (!dir.exists(audio_dir)) dir.create(audio_dir)
addResourcePath("audio_files", audio_dir)

ui <- page_navbar(
  id = "nav_id",
  title = "Vocal Type Assessor",
  theme = bs_theme(version = 5, bootswatch = "flatly"),
  bg = "#2c3e50",
  
  # --- CUSTOM FAVICON & STYLING ---
  header = tags$head(
    tags$link(rel = "icon", href = "data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><text x='50%' y='50%' dominant-baseline='central' text-anchor='middle' font-size='75'>🎧</text></svg>"),
    tags$meta(name = "viewport", content = "width=device-width, initial-scale=1"),
    tags$style(HTML("
      .compact-card { max-width: 600px; margin: auto; padding: 15px; }
      .audio-player-container audio { width: 100%; margin-top: 5px; margin-bottom: 5px; }
      body { background-color: #f8f9fa; }
      /* Replace blue with button green and make bold */
      .navbar-nav .nav-link.active, .navbar-nav .show > .nav-link { color: #1abc9c !important; font-weight: bold !important; }
      .text-primary { color: #1abc9c !important; font-weight: bold !important; }
    ")),
    tags$script(HTML("
      $(document).on('keydown', function(e) {
        if (e.key === 'Enter') {
          var saveBtn = document.getElementById('save_btn');
          if (saveBtn && document.activeElement.tagName !== 'BUTTON') {
            saveBtn.click();
            e.preventDefault();
          }
        }
      });
    "))
  ),
  
  nav_panel("Review",
            div(class = "container-fluid py-2",
                uiOutput("main_content")
            )
  ),
  nav_panel("Data Table", 
            div(class = "container-fluid py-2",
                div(class = "d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2",
                    p("Click a row in the table to jump to that file's review.", class = "mb-0 text-muted"),
                    uiOutput("download_btn_ui")
                ),
                div(class = "table-responsive", DTOutput("results_table"))
            )
  )
)

server <- function(input, output, session) {
  current_idx <- reactiveVal(1)
  last_autosave <- reactiveVal(NULL) # Tracker for autosave time
  
  # Initialize data frame structure
  results_df <- reactiveVal(data.frame(
    Name = character(), 
    Transcription = character(),
    Comment = character(),
    Date_Reviewed = character(),
    stringsAsFactors = FALSE
  ))
  
  observeEvent(input$files, {
    # --- AUTOSAVE RESTORE LOGIC ---
    snapshot_file <- "vocal_review_snapshot.rds"
    
    if (file.exists(snapshot_file)) {
      snapshot <- readRDS(snapshot_file)
      if (identical(sort(input$files$name), sort(snapshot$files))) {
        results_df(snapshot$results)
        current_idx(snapshot$idx)
        showNotification("Previous session memory restored successfully!", type = "message", duration = 5)
        return() 
      }
    }
    
    df <- data.frame(
      Name = input$files$name, 
      Transcription = "",
      Comment = "",
      Date_Reviewed = "",
      stringsAsFactors = FALSE
    )
    results_df(df)
    current_idx(1)
  })
  
  get_current_datapath <- function() {
    req(input$files, current_idx() <= nrow(results_df()))
    target_filename <- results_df()$Name[current_idx()]
    match_idx <- match(target_filename, input$files$name)
    if (is.na(match_idx)) return(NULL)
    return(input$files$datapath[match_idx])
  }
  
  output$pre_upload_info <- renderUI({
    if (is.null(input$files)) {
      helpText("To resume a previous session, re-upload exact .wav files. Progress will restore automatically.", 
               style = "font-size: 0.8em; color: #6c757d; margin-top: 4px;")
    }
  })
  
  output$progress_ui <- renderUI({
    req(input$files)
    total <- nrow(results_df())
    current <- min(current_idx(), total)
    perc <- round((current / total) * 100)
    
    tagList(
      div(class = "d-flex justify-content-between align-items-center mb-1",
          span(paste("Progress:", current, "of", total), style = "font-weight: bold; font-size: 0.9em;"),
          span(paste0(perc, "%"), style = "font-size: 0.85em; color: #6c757d;")
      ),
      div(class = "progress", style = "height: 12px;",
          div(class = "progress-bar progress-bar-striped bg-info", 
              role = "progressbar", 
              style = paste0("width: ", perc, "%;"))
      )
    )
  })
  
  observeEvent(input$results_table_rows_selected, {
    req(input$results_table_rows_selected)
    idx <- input$results_table_rows_selected
    
    save_current_row()
    
    current_idx(idx)
    update_inputs_with_row_data(idx)
    nav_select("nav_id", "Review")
  })
  
  output$main_content <- renderUI({
    if (is.null(input$files)) {
      div(class = "card compact-card shadow-sm mt-4 text-center",
          div(class = "card-body",
              h3("Vocal Type Assessor", class = "card-title mb-3"),
              p("Select your .wav files to begin review.", class = "text-muted mb-4"),
              fileInput("files", NULL, multiple = TRUE, accept = ".wav", buttonLabel = "Upload Files", placeholder = "", width = "100%"),
              uiOutput("pre_upload_info")
          )
      )
    } else if (current_idx() > nrow(results_df())) {
      div(class = "card compact-card shadow-sm mt-4 text-center",
          div(class = "card-body",
              h2("Review Complete!", class = "card-title text-success mb-3"),
              p("All files have been processed.", class = "card-title text-success mb-3"),
              p("Download your local copy and back up to Drive below.", class = "text-muted mb-4"),
              div(class = "d-flex flex-column gap-3 align-items-stretch",
                  uiOutput("complete_download_ui"),
                  uiOutput("gdrive_sync_ui")
              ),
              hr(class = "my-4"),
              fileInput("files", NULL, multiple = TRUE, accept = ".wav", buttonLabel = "Replace Files", placeholder = "", width = "100%")
          )
      )
    } else {
      div(class = "card compact-card shadow-sm mt-2",
          div(class = "card-body py-3 px-3",
              # Top bar: File upload switcher & progress
              div(class = "d-flex justify-content-between align-items-center mb-2 flex-wrap gap-2",
                  fileInput("files", NULL, multiple = TRUE, accept = ".wav", buttonLabel = "Replace Files", placeholder = ""),
                  div(style = "flex-grow: 1; min-width: 150px;", uiOutput("progress_ui"))
              ),
              hr(class = "my-2"),
              
              # Current file header & audio player
              div(class = "text-center mb-2",
                  h5(textOutput("current_filename"), class = "text-primary text-truncate mb-1")
              ),
              div(class = "audio-player-container text-center",
                  uiOutput("audio_container")
              ),
              hr(class = "my-2"),
              
              # Inputs
              textInput("transcription", "Transcription (Mandatory):", value = results_df()$Transcription[current_idx()], width = "100%"),
              textInput("comment", "Comment (Optional, e.g. 'the sound is not clear', 'not sure'):", value = results_df()$Comment[current_idx()], width = "100%"),
              
              # Action buttons
              div(class = "d-flex gap-2 mt-3",
                  if (current_idx() > 1) actionButton("back", "Previous", class = "btn-secondary flex-fill"),
                  actionButton("save_btn", "Save & Next", class = "btn-success flex-fill")
              ),
              
              # Autosave indicator
              if (!is.null(last_autosave())) {
                div(paste("✔ Autosaved at", format(last_autosave(), "%H:%M:%S")),
                    style = "color: #198754; font-size: 0.8em; text-align: center; margin-top: 8px;")
              }
          )
      )
    }
  })
  
  output$audio_container <- renderUI({
    req(input$files)
    path <- get_current_datapath()
    req(path)
    
    unique_id <- as.integer(Sys.time())
    filename <- paste0("temp_", current_idx(), "_", unique_id, ".wav")
    file.copy(path, file.path(audio_dir, filename), overwrite = TRUE)
    
    tags$audio(src = paste0("audio_files/", filename), type = "audio/wav", controls = TRUE, autoplay = TRUE)
  })
  
  save_current_row <- function() {
    df <- results_df()
    idx <- current_idx()
    df$Transcription[idx] <- if(!is.null(input$transcription)) input$transcription else ""
    df$Comment[idx] <- if(!is.null(input$comment)) input$comment else ""
    df$Date_Reviewed[idx] <- format(Sys.time(), "%Y-%m-%d %H:%M:%S")
    results_df(df)
    
    if (!is.null(input$files)) {
      snapshot <- list(
        results = df,
        idx = current_idx(),
        files = input$files$name
      )
      saveRDS(snapshot, "vocal_review_snapshot.rds")
      last_autosave(Sys.time())
    }
  }
  
  update_inputs_with_row_data <- function(idx) {
    row <- results_df()[idx, ]
    updateTextInput(session, "transcription", value = row$Transcription)
    updateTextInput(session, "comment", value = row$Comment)
  }
  
  observeEvent(input$save_btn, {
    if (is.null(input$transcription) || trimws(input$transcription) == "") {
      showNotification("Please provide a transcription before proceeding.", type = "warning")
      return()
    }
    
    save_current_row()
    
    if(current_idx() <= nrow(results_df())) {
      current_idx(current_idx() + 1)
      if(current_idx() <= nrow(results_df())) {
        update_inputs_with_row_data(current_idx())
      }
    }
  })
  
  observeEvent(input$back, {
    save_current_row()
    if(current_idx() > 1) {
      current_idx(current_idx() - 1)
      update_inputs_with_row_data(current_idx())
    }
  })
  
  output$results_table <- renderDT({ 
    datatable(results_df(), selection = 'single', options = list(pageLength = 10, scrollX = TRUE))
  })
  
  output$current_filename <- renderText({ 
    req(input$files)
    if(current_idx() <= nrow(results_df())) {
      results_df()$Name[current_idx()]
    }
  })
  
  get_csv_uri <- function() {
    df <- results_df()
    con <- textConnection(NULL, "w", encoding = "UTF-8")
    write.csv(df, con, row.names = FALSE, fileEncoding = "UTF-8")
    csv_text <- textConnectionValue(con)
    close(con)
    csv_string <- paste(csv_text, collapse = "\n")
    utf8_csv <- paste0("\xEF\xBB\xBF", csv_string)
    paste0("data:text/csv;charset=utf-8,", URLencode(utf8_csv, reserved = TRUE))
  }
  
  output$download_btn_ui <- renderUI({
    uri <- get_csv_uri()
    filename <- paste0("Review_", format(Sys.Date(), "%Y-%m-%d"), ".csv")
    tags$a("Export Table to CSV", href = uri, download = filename, class = "btn btn-primary btn-sm")
  })
  
  output$complete_download_ui <- renderUI({
    uri <- get_csv_uri()
    filename <- paste0("Review_", format(Sys.Date(), "%Y-%m-%d"), ".csv")
    tags$a("Download CSV Report", href = uri, download = filename, class = "btn btn-success w-100")
  })
  
  output$gdrive_sync_ui <- renderUI({
    df <- results_df()
    con <- textConnection(NULL, "w", encoding = "UTF-8")
    write.csv(df, con, row.names = FALSE, fileEncoding = "UTF-8")
    csv_text <- textConnectionValue(con)
    close(con)
    csv_string <- paste(csv_text, collapse = "\n")
    utf8_csv <- paste0("\xEF\xBB\xBF", csv_string)
    
    filename <- paste0("Review_", format(Sys.Date(), "%Y-%m-%d"), "_", format(Sys.time(), "%H%M%S"), ".csv")
    
    tagList(
      tags$script(HTML(sprintf("
        function sendToDrive() {
          var btn = document.getElementById('sync_gdrive_btn');
          var originalText = btn.innerHTML;
          btn.innerHTML = 'Wait for sending confirmation...';
          btn.disabled = true;
          
          var webhookUrl = 'https://script.google.com/macros/s/AKfycbxwhMGmWHsCtetsaHi22WnD2nZGopK7TZ_V7yKq5c32zqovkv-eu87C8aAQ1upMlHQl/exec';
          var payload = {
            filename: %s,
            csv: %s
          };
          
          fetch(webhookUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'text/plain;charset=utf-8' },
            body: JSON.stringify(payload)
          })
          .then(response => response.json())
          .then(data => {
            btn.innerHTML = originalText;
            btn.disabled = false;
            if(data.status === 'success') {
              alert('Results successfully backed up to Google Drive!');
            } else {
              alert('Google Drive Error: ' + data.message);
            }
          })
          .catch(error => {
            btn.innerHTML = originalText;
            btn.disabled = false;
            console.error('Error:', error);
            alert('Failed to sync to Google Drive. Check browser console for details.');
          });
        }
      ", jsonlite::toJSON(filename, auto_unbox = TRUE), 
                               jsonlite::toJSON(utf8_csv, auto_unbox = TRUE)))),
      
      actionButton("sync_gdrive_btn", "Backup Results to Aitana's Drive", 
                   class = "btn btn-info w-100", 
                   onclick = "sendToDrive();")
    )
  })
}

shinyApp(ui, server)
